.dm-lcx-bar i.dm-ok{background:var(--dm-ok)}.dm-lcx-bar i.dm-bad{background:var(--dm-bad)}.dm-lcx-bar i.dm-run{background:var(--dm-accent-mark,var(--dm-accent));opacity:.5}
.dm-lcx-list{display:flex;flex-direction:column}
